(async()=>{try{if(!navigator.locks)throw Error('請使用支援安全存檔的新版瀏覽器');await navigator.locks.request(Summon.key,()=>Onboarding.migrate(localStorage));const o=Onboarding.status(localStorage);if(!o.complete){location.replace(!o.intro?'tutorial.html':!o.first?'summon.html':'portrait.html?tutorial=1')}}catch(e){const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='遊戲進度無法讀取：'+e.message;document.querySelector('main').prepend(p)}})();
